// Quiet blue-green mountain lake at first light — direct 2D canvas painting
(function () {
  const horizon = 350;

  // ---------- noise helpers ----------
  function hash(x, y) {
    let n = Math.sin(x * 127.1 + y * 311.7) * 43758.5453123;
    return n - Math.floor(n);
  }
  function vnoise(x, y) {
    const xi = Math.floor(x), yi = Math.floor(y);
    const xf = x - xi, yf = y - yi;
    const u = xf * xf * (3 - 2 * xf);
    const v = yf * yf * (3 - 2 * yf);
    const a = hash(xi, yi), b = hash(xi + 1, yi);
    const c = hash(xi, yi + 1), d = hash(xi + 1, yi + 1);
    return a * (1 - u) * (1 - v) + b * u * (1 - v) + c * (1 - u) * v + d * u * v;
  }
  function fbm(x, y, oct, lac, gain) {
    let amp = 0.5, freq = 1, sum = 0, norm = 0;
    for (let i = 0; i < oct; i++) {
      sum += amp * vnoise(x * freq, y * freq);
      norm += amp;
      amp *= gain; freq *= lac;
    }
    return sum / norm;
  }
  // ridge line base: sum of a few sines + fbm
  function ridge(x, layer) {
    const s = 0.0016 + layer * 0.0005;
    let y = 0;
    y += Math.sin(x * s + layer * 3.1) * (34 - layer * 3);
    y += Math.sin(x * s * 2.3 + layer * 1.7) * (16 - layer * 2);
    y += Math.sin(x * s * 5.1 + layer * 4.2) * (7 - layer);
    y += (fbm(x * 0.006 + layer * 10, layer * 5.3, 4, 2.1, 0.55) - 0.5) * (46 - layer * 6);
    return y;
  }

  const glowX = W * 0.575;
  const glowY = horizon - 20;

  // ---------- sky ----------
  const sky = ctx.createLinearGradient(0, 0, 0, horizon + 20);
  sky.addColorStop(0.0, '#212f3f');
  sky.addColorStop(0.28, '#38505f');
  sky.addColorStop(0.55, '#657f88');
  sky.addColorStop(0.78, '#a6b3ac');
  sky.addColorStop(0.92, '#dcbfa0');
  sky.addColorStop(1.0, '#eecaa8');
  ctx.fillStyle = sky;
  ctx.fillRect(0, 0, W, horizon + 20);

  // warm glow mass near horizon, right of centre
  const glow = ctx.createRadialGradient(glowX, glowY, 8, glowX, glowY, W * 0.72);
  glow.addColorStop(0.0, 'rgba(255,224,180,0.85)');
  glow.addColorStop(0.18, 'rgba(250,206,162,0.55)');
  glow.addColorStop(0.45, 'rgba(232,190,158,0.24)');
  glow.addColorStop(1.0, 'rgba(180,175,175,0.0)');
  ctx.fillStyle = glow;
  ctx.fillRect(0, 0, W, horizon + 30);

  // pale quiet corridor spreading left along the horizon
  const corr = ctx.createLinearGradient(glowX, 0, W * 0.05, 0);
  corr.addColorStop(0, 'rgba(255,228,196,0.42)');
  corr.addColorStop(0.5, 'rgba(238,214,190,0.16)');
  corr.addColorStop(1, 'rgba(210,205,200,0.0)');
  ctx.fillStyle = corr;
  ctx.fillRect(0, horizon - 70, W, 120);

  // ---------- cloud wisps ----------
  function wisp(cx, cy, len, thick, alpha, tint) {
    ctx.save();
    ctx.globalAlpha = alpha;
    ctx.fillStyle = tint;
    ctx.beginPath();
    const steps = 40;
    for (let i = 0; i <= steps; i++) {
      const t = i / steps;
      const x = cx - len / 2 + len * t;
      const taper = Math.sin(Math.PI * t);
      const y = cy + Math.sin(t * 6.2 + cx) * thick * 1.4 - taper * thick * 0.4;
      const rx = (len / 2) * 0.06 + 4;
      ctx.ellipse(x, y, rx + taper * len * 0.05, thick * taper * 0.9 + 2, 0, 0, Math.PI * 2);
    }
    ctx.fill();
    ctx.restore();
  }
  for (let i = 0; i < 26; i++) {
    const cy = 40 + rng() * (horizon - 90);
    const warm = fbm(i * 3.7, 2.1, 3, 2, 0.5);
    const tint = warm > 0.55 ? 'rgba(255,222,196,0.9)' : 'rgba(190,198,205,0.9)';
    wisp(rng() * W, cy, 220 + rng() * 520, 5 + rng() * 9, 0.06 + rng() * 0.12, tint);
  }
  // a couple of brighter streaks catching the light near glow
  for (let i = 0; i < 5; i++) {
    wisp(glowX - 260 + rng() * 480, 140 + rng() * 130, 260 + rng() * 320, 4 + rng() * 5,
      0.14 + rng() * 0.10, 'rgba(255,231,205,0.95)');
  }

  // ---------- ridgelines ----------
  function drawRidge(layer, baseY, colorTop, colorBot, darkness) {
    ctx.beginPath();
    ctx.moveTo(0, horizon + 40);
    for (let x = 0; x <= W; x += 4) {
      ctx.lineTo(x, baseY + ridge(x, layer));
    }
    ctx.lineTo(W, horizon + 40);
    ctx.closePath();
    const g = ctx.createLinearGradient(0, baseY - 80, 0, horizon);
    g.addColorStop(0, colorTop);
    g.addColorStop(1, colorBot);
    ctx.fillStyle = g;
    ctx.fill();
    // hazy glow rim on the light side
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    ctx.globalAlpha = 0.12;
    const rim = ctx.createLinearGradient(glowX, baseY - 60, glowX - 400, baseY);
    rim.addColorStop(0, 'rgba(255,214,170,0.9)');
    rim.addColorStop(1, 'rgba(255,214,170,0)');
    ctx.fillStyle = rim;
    ctx.fill();
    ctx.restore();
  }

  // layer 3 (farthest) : pale blue-gray
  drawRidge(3, 300, 'rgba(150,166,180,0.95)', 'rgba(120,140,158,0.95)');
  // mist band
  function mistBand(y, h, a) {
    const g = ctx.createLinearGradient(0, y - h, 0, y + h);
    g.addColorStop(0, 'rgba(214,216,214,0)');
    g.addColorStop(0.5, 'rgba(220,221,216,' + a + ')');
    g.addColorStop(1, 'rgba(214,216,214,0)');
    ctx.fillStyle = g;
    ctx.fillRect(0, y - h, W, h * 2);
  }
  mistBand(316, 16, 0.55);

  drawRidge(2, 322, 'rgba(96,120,132,0.97)', 'rgba(74,98,110,0.97)');
  mistBand(334, 12, 0.45);

  drawRidge(1, 340, 'rgba(58,84,92,0.98)', 'rgba(46,70,80,0.98)');
  mistBand(348, 9, 0.38);

  // small broken distant pine shore at the waterline
  ctx.save();
  ctx.fillStyle = 'rgba(40,60,62,0.92)';
  for (let i = 0; i < 260; i++) {
    const x = rng() * W;
    const away = Math.abs(x - glowX) / glowX;
    if (rng() < 0.3) continue;
    const bx = 344 + ridge(x, 0) * 0.4 + rng() * 6 - 2;
    const h = 4 + rng() * 9 * (1 - 0.4 * away);
    const w = 0.9 + rng() * 1.3;
    ctx.beginPath();
    ctx.moveTo(x - w, bx);
    ctx.lineTo(x, bx - h);
    ctx.lineTo(x + w, bx);
    ctx.closePath();
    ctx.fill();
  }
  ctx.restore();

  // ---------- water ----------
  const waterG = ctx.createLinearGradient(0, horizon, 0, H);
  waterG.addColorStop(0, '#93a4a6');
  waterG.addColorStop(0.25, '#789193');
  waterG.addColorStop(0.6, '#547476');
  waterG.addColorStop(1, '#3a5759');
  ctx.fillStyle = waterG;
  ctx.fillRect(0, horizon, W, H - horizon);

  // reflected warm corridor
  const wcorr = ctx.createRadialGradient(glowX, horizon + 30, 10, glowX, horizon + 80, W * 0.55);
  wcorr.addColorStop(0, 'rgba(250,222,188,0.55)');
  wcorr.addColorStop(0.4, 'rgba(220,205,190,0.22)');
  wcorr.addColorStop(1, 'rgba(180,185,185,0.0)');
  ctx.fillStyle = wcorr;
  ctx.fillRect(0, horizon, W, H - horizon);

  // reflected ridges — coarse colour bands
  function reflectBand(srcY, colorA, colorB, alpha) {
    const depth = (srcY - 260) * 1.0;
    const y0 = horizon + Math.max(2, (srcY - horizon) * 0.05 + depth * 0.05);
    const h = 28 + (horizon - srcY) * 0.6;
    const g = ctx.createLinearGradient(0, y0, 0, y0 + h);
    g.addColorStop(0, colorA);
    g.addColorStop(1, colorB);
    ctx.globalAlpha = alpha;
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.moveTo(0, y0);
    for (let x = 0; x <= W; x += 8) {
      const wav = Math.sin(x * 0.02 + srcY) * 3 + (fbm(x * 0.01, srcY, 3, 2, 0.5) - 0.5) * 8;
      ctx.lineTo(x, y0 + wav);
    }
    for (let x = W; x >= 0; x -= 8) {
      const wav = Math.sin(x * 0.025 + srcY * 0.7) * 5 + (fbm(x * 0.012, srcY + 7, 3, 2, 0.5) - 0.5) * 10;
      ctx.lineTo(x, y0 + h + wav);
    }
    ctx.closePath();
    ctx.fill();
    ctx.globalAlpha = 1;
  }
  reflectBand(300, 'rgba(150,164,176,0.55)', 'rgba(120,140,155,0.0)', 0.7);
  reflectBand(322, 'rgba(96,118,130,0.6)', 'rgba(70,96,108,0.0)', 0.7);
  reflectBand(340, 'rgba(52,78,86,0.6)', 'rgba(44,68,76,0.0)', 0.6);

  // ---------- water texture strokes ----------
  // short horizontal broken strokes, widening toward the foreground
  const dabs = 4200;
  for (let i = 0; i < dabs; i++) {
    const p = Math.pow(rng(), 0.65); // denser near horizon
    const y = horizon + 6 + p * (H - horizon - 8);
    const depth = (y - horizon) / (H - horizon);
    const x = rng() * W;
    const distFromCorridor = Math.abs(x - glowX + depth * 190);
    const corridorFade = Math.exp(-(distFromCorridor * distFromCorridor) / (2 * (140 + depth * 300) * (140 + depth * 300)));
    const len = 2 + depth * 20 + rng() * (2 + depth * 14);
    const broken = 1.2 + depth * 2.5;
    const alpha = (0.06 + rng() * 0.16) * (1 - 0.7 * corridorFade);

    // colour: light on top of strokes, darker below
    const lit = fbm(x * 0.01, y * 0.05, 3, 2, 0.5);
    let col;
    if (lit > 0.58) col = 'rgba(190,206,205,1)';
    else if (lit > 0.42) col = 'rgba(120,148,148,1)';
    else col = 'rgba(58,86,88,1)';
    ctx.globalAlpha = alpha;
    ctx.strokeStyle = col;
    ctx.lineWidth = 0.6 + depth * 1.4;
    ctx.beginPath();
    const segs = 1 + Math.floor(rng() * 2);
    for (let s = 0; s < segs; s++) {
      const sx = x + (rng() - 0.5) * broken * 3;
      const sy = y + (rng() - 0.5) * 2.2;
      ctx.moveTo(sx, sy);
      ctx.lineTo(sx + len, sy + (rng() - 0.5) * 1.2);
    }
    ctx.stroke();
  }
  ctx.globalAlpha = 1;

  // brighter shimmers in the corridor
  for (let i = 0; i < 900; i++) {
    const depth = Math.pow(rng(), 0.6);
    const y = horizon + 8 + depth * (H - horizon);
    const spread = 90 + depth * 320;
    const x = glowX - depth * 170 + (rng() - 0.5) * spread * 2;
    const alpha = (0.12 + rng() * 0.22) * (1 - depth * 0.4);
    const len = 3 + depth * 16 + rng() * 8;
    ctx.strokeStyle = 'rgba(255,240,220,1)';
    ctx.globalAlpha = alpha;
    ctx.lineWidth = 0.7 + depth * 1.0;
    ctx.beginPath();
    ctx.moveTo(x, y);
    ctx.lineTo(x + len, y + (rng() - 0.5) * 1.5);
    ctx.stroke();
  }
  ctx.globalAlpha = 1;

  // ---------- far-left pine cluster (framing) ----------
  function branch(x, y, len, ang, depth, maxDepth) {
    if (depth > maxDepth || len < 3) return;
    const x2 = x + Math.cos(ang) * len;
    const y2 = y + Math.sin(ang) * len;
    // trunk colour varies with depth, lighter at tips
    const shade = 0.35 + depth * 0.06;
    ctx.strokeStyle = 'rgba(' + Math.floor(38 + depth * 4) + ',' + Math.floor(52 + depth * 5) + ',' + Math.floor(44 + depth * 4) + ',0.95)';
    ctx.lineWidth = Math.max(0.6, (maxDepth - depth) * 1.4);
    ctx.lineCap = 'round';
    ctx.beginPath();
    ctx.moveTo(x, y);
    ctx.lineTo(x2, y2);
    ctx.stroke();

    // needle tufts near the tips
    if (depth >= 2) {
      const tufts = 3 + Math.floor(rng() * 3);
      for (let t = 0; t < tufts; t++) {
        const tx = x2 + (rng() - 0.5) * 14;
        const ty = y2 + (rng() - 0.5) * 14;
        const nl = 3 + rng() * 6;
        const na = rng() * Math.PI * 2;
        ctx.strokeStyle = 'rgba(' + Math.floor(48 + rng() * 24) + ',' + Math.floor(72 + rng() * 26) + ',' + Math.floor(56 + rng() * 20) + ',' + (0.55 + rng() * 0.35) + ')';
        ctx.lineWidth = 0.7 + rng() * 0.8;
        ctx.beginPath();
        ctx.moveTo(tx, ty);
        ctx.lineTo(tx + Math.cos(na) * nl, ty + Math.sin(na) * nl);
        ctx.stroke();
      }
    }

    const n = depth < 1 ? 2 : 3;
    for (let b = 0; b < n; b++) {
      const spread = 0.5 + rng() * 0.35;
      const na = ang + (rng() - 0.5) * spread * 2 + (b % 2 === 0 ? -0.35 : 0.35);
      branch(x2, y2, len * (0.62 + rng() * 0.12), na, depth + 1, maxDepth);
    }
  }
  // main trunks at far left
  ctx.save();
  // faint darker mass for cluster body
  const clusterG = ctx.createRadialGradient(90, 380, 20, 90, 380, 320);
  clusterG.addColorStop(0, 'rgba(20,40,36,0.55)');
  clusterG.addColorStop(1, 'rgba(20,40,36,0.0)');
  ctx.fillStyle = clusterG;
  ctx.fillRect(0, 120, 380, 560);
  ctx.restore();

  branch(70, 800, 130, -Math.PI / 2 - 0.08, 0, 5);
  branch(140, 800, 150, -Math.PI / 2 + 0.12, 0, 5);
  branch(30, 800, 120, -Math.PI / 2 - 0.22, 0, 4);
  branch(210, 800, 105, -Math.PI / 2 + 0.3, 0, 4);

  // ---------- lower-left bank: stones and reeds ----------
  ctx.save();
  // bank earth
  const bank = ctx.createLinearGradient(0, 660, 0, H);
  bank.addColorStop(0, 'rgba(58,66,58,0.0)');
  bank.addColorStop(0.4, 'rgba(48,54,48,0.75)');
  bank.addColorStop(1, 'rgba(30,36,32,0.95)');
  ctx.fillStyle = bank;
  ctx.beginPath();
  ctx.moveTo(0, 700);
  ctx.bezierCurveTo(120, 690, 210, 730, 300, 760);
  ctx.lineTo(300, H);
  ctx.lineTo(0, H);
  ctx.closePath();
  ctx.fill();

  // stones
  function stone(cx, cy, rx, ry, warm) {
    const g = ctx.createRadialGradient(cx - rx * 0.3, cy - ry * 0.4, 1, cx, cy, rx * 1.2);
    if (warm) {
      g.addColorStop(0, 'rgba(150,138,122,1)');
      g.addColorStop(0.6, 'rgba(96,92,84,1)');
      g.addColorStop(1, 'rgba(50,52,50,1)');
    } else {
      g.addColorStop(0, 'rgba(126,128,124,1)');
      g.addColorStop(0.6, 'rgba(78,84,84,1)');
      g.addColorStop(1, 'rgba(42,48,50,1)');
    }
    ctx.save();
    ctx.beginPath();
    const steps = 26;
    for (let i = 0; i <= steps; i++) {
      const a = (i / steps) * Math.PI * 2;
      const jitter = (fbm(Math.cos(a) * 2 + cx * 0.01, Math.sin(a) * 2, 3, 2, 0.5) - 0.5) * 0.25;
      const px = cx + Math.cos(a) * rx * (1 + jitter);
      const py = cy + Math.sin(a) * ry * (1 + jitter);
      if (i === 0) ctx.moveTo(px, py); else ctx.lineTo(px, py);
    }
    ctx.closePath();
    ctx.fillStyle = g;
    ctx.fill();
    ctx.clip();
    // fine speckle
    for (let i = 0; i < 40; i++) {
      ctx.globalAlpha = 0.05 + rng() * 0.08;
      ctx.fillStyle = rng() > 0.5 ? 'rgba(220,215,200,1)' : 'rgba(30,34,34,1)';
      ctx.fillRect(cx - rx + rng() * rx * 2, cy - ry + rng() * ry * 2, 1.5, 1);
    }
    ctx.restore();
  }
  stone(140, 742, 46, 24, true);
  stone(220, 768, 34, 18, false);
  stone(70, 776, 40, 22, false);
  stone(178, 780, 26, 14, true);

  // reeds
  function reed(x, baseY, len, bend, alpha) {
    ctx.strokeStyle = 'rgba(74,84,56,' + alpha + ')';
    ctx.lineWidth = 1.2 + rng() * 0.8;
    ctx.beginPath();
    ctx.moveTo(x, baseY);
    ctx.quadraticCurveTo(x + bend * 0.4, baseY - len * 0.55, x + bend, baseY - len);
    ctx.stroke();
    // seed head
    ctx.fillStyle = 'rgba(96,92,64,' + alpha + ')';
    ctx.beginPath();
    ctx.ellipse(x + bend, baseY - len, 1.6, 4.5, bend * 0.02, 0, Math.PI * 2);
    ctx.fill();
  }
  const reedBase = [[60, 770], [92, 782], [120, 772], [150, 760], [40, 760], [175, 748], [105, 792]];
  for (let i = 0; i < reedBase.length; i++) {
    const rb = reedBase[i];
    for (let k = 0; k < 3; k++) {
      reed(rb[0] + (rng() - 0.5) * 10, rb[1], 90 + rng() * 130, (rng() - 0.5) * 26, 0.55 + rng() * 0.35);
    }
  }
  ctx.restore();

  // gentle atmospheric wash overall to unify
  const wash = ctx.createLinearGradient(0, 0, 0, H);
  wash.addColorStop(0, 'rgba(120,140,150,0.05)');
  wash.addColorStop(0.45, 'rgba(210,205,195,0.04)');
  wash.addColorStop(1, 'rgba(40,60,60,0.05)');
  ctx.fillStyle = wash;
  ctx.fillRect(0, 0, W, H);

  // subtle vignette
  const vig = ctx.createRadialGradient(W * 0.5, H * 0.46, H * 0.25, W * 0.5, H * 0.5, H * 0.92);
  vig.addColorStop(0, 'rgba(0,0,0,0)');
  vig.addColorStop(1, 'rgba(6,12,16,0.34)');
  ctx.fillStyle = vig;
  ctx.fillRect(0, 0, W, H);
})();
